// Short whole-string hints (status hints like "Ringing", Q.850 "User busy").
const WHOLE = {
  Ringing: ["Tocando", "Sonando", "Klingelt"],
  Queued: ["Na fila", "En cola", "In Warteschlange"],
  Accepted: ["Aceito", "Aceptado", "Angenommen"],
  "Busy here": ["Ocupado", "Ocupado", "Besetzt"],
  "Not implemented": ["Não implementado", "No implementado", "Nicht implementiert"],
  Declined: ["Recusada", "Rechazada", "Abgelehnt"],
  "User busy": ["Usuário ocupado", "Usuario ocupado", "Teilnehmer besetzt"],
  "Call rejected": ["Chamada rejeitada", "Llamada rechazada", "Anruf abgewiesen"],
};

const TOK = { "{}": "(.+?)", "{w}": "(\\S+?)", "{n}": "(\\d+(?:\\.\\d+)?)" };
let compiled = null;
function compile() {
  compiled = E.map(([src, ...tr]) => {
    // The English is literal text except tokens and the regex bits we wrote on purpose (\\., \\(, ^, $, lookaheads).
    let re = "";
    for (let i = 0; i < src.length; ) {
      const tok = Object.keys(TOK).find((k) => src.startsWith(k, i));
      if (tok) {
        re += TOK[tok];
        i += tok.length;
      } else if (src[i] === "\\") {
        re += src.slice(i, i + 2);
        i += 2;
      } else if (src.startsWith("(?=", i)) {
        const j = src.indexOf(")", i);
        re += src.slice(i, j + 1);
        i = j + 1;
      } else if ((src[i] === "^" && i === 0) || (src[i] === "$" && i === src.length - 1)) {
        re += src[i++];
      } else {
        re += src[i].replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        i++;
      }
    }
    // A sentence ending in a token is closed by the end of the text or the next sentence.
    if (/\((?:\.\+\?|\\S\+\?)\)$/.test(re)) re += "(?=$|[.;,]\\s|\\.$)";
    return [new RegExp(re, "g"), tr];
  });
  // Longest English first so a full sentence wins over a fragment of it.
  compiled.sort((a, b) => b[0].source.length - a[0].source.length);
}

/// Translates a finding title or detail to the current language.
export function trFinding(text) {
  const i = { pt: 0, es: 1, de: 2 }[currentLang()];
  if (i == null || !text) return text;
  if (WHOLE[text.trim()]) return WHOLE[text.trim()][i];
  if (!compiled) compile();
  let out = text;
  for (const [re, tr] of compiled) {
    re.lastIndex = 0;
    out = out.replace(re, tr[i]);
  }
  // A short hint at the end of "Final response 486 Busy Here. Busy here".
  out = out.replace(/(\.\s)([A-Z][a-z]+(?: [a-z]+)?)$/, (m, sep, h) => (WHOLE[h] ? sep + WHOLE[h][i] : m));
  return out;
}
